<script setup>
import {shallowRef,watch,nextTick,onUnmounted,computed} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {modal,closeModal,session,login,logout} from '../session'
import {navGroups,path,fmt} from '../data'
import Icon from './Icon.vue'
import {locale,languages,applyLocale} from '../i18n'
import Coin from './Coin.vue'
const dialog=shallowRef(null),current=shallowRef(null),closing=shallowRef(false),amount=shallowRef(''),error=shallowRef(''),done=shallowRef(false),expanded=shallowRef(''),message=shallowRef('')
const route=useRoute(),router=useRouter();let trigger,previousOverflow,closeTimer
const isDrawer=computed(()=>current.value?.type==='menu')
const formType=computed(()=>['subscribe','donate','order','convert','loan','c2c'].includes(current.value?.type))
const estimate=computed(()=>Number(amount.value||0)*Number(current.value?.data.rate||0)/100*Math.max(1,Number(current.value?.data.days||1)))
watch(modal,async(value)=>{if(!value)return;current.value=value;amount.value=String(value.data.amount||'');error.value='';done.value=false;closing.value=false;expanded.value='';message.value=value.data.value||'';trigger=document.activeElement;previousOverflow=document.body.style.overflow;await nextTick();dialog.value.showModal();document.body.style.overflow='hidden';await nextTick();dialog.value.querySelector('[data-initial-focus]')?.focus()})
function cleanup(){document.body.style.overflow=previousOverflow??'';if(trigger?.isConnected)trigger.focus();clearTimeout(closeTimer)}
function close(){if(closing.value||!current.value)return;closing.value=true;closeTimer=setTimeout(()=>{dialog.value?.close();current.value=null;closeModal();closing.value=false;cleanup()},matchMedia('(prefers-reduced-motion: reduce)').matches?0:150)}
function cancel(e){e.preventDefault();if(amount.value&&!done.value){error.value='尚有未提交內容，請使用右上角關閉或取消退出。';return}close()}
function changeLanguage(l){applyLocale(l);close();router.replace({path:route.path.replace(/^\/[^/]+/,'/'+l),query:route.query,hash:route.hash})}
function accountAction(){if(done.value)return;if(current.value.type==='account-edit'){if(!message.value.trim()){error.value='請輸入用戶名';return}current.value.data.onSave?.(message.value.trim())}else current.value.data.onConfirm?.();done.value=true;close()}
function navigate(to){close();router.push(path(to))}
function submit(){if(done.value)return;const val=Number(amount.value),min=current.value.data.min??0.01;if(!Number.isFinite(val)||val<min){error.value=`請輸入不低於 ${fmt(min)} 的有效金額。`;return}if(val>(current.value.data.max??500000)){error.value='金額超過單次上限。';return}if(session.mode!=='模擬'&&current.value.type!=='loan'){error.value='可用餘額不足。這是本地演示，切換至「模擬」可體驗操作。';return}if(val>100000){error.value='模擬可用餘額不足。';return}error.value='';done.value=true;current.value.data.onConfirm?.(val);if(current.value.type==='subscribe')session.subscriptions.push({name:current.value.data.name,amount:val,status:'運行中'});if(current.value.type==='order')session.orders.push({name:current.value.data.name,amount:val,symbol:current.value.data.symbol||'USD',side:current.value.data.side,status:'已建立（模擬）'});amount.value=''}
function keydown(e){if(e.key!=='Tab')return;const els=[...dialog.value.querySelectorAll('button:not([disabled]),a[href],input:not([disabled]),select,textarea,[tabindex="0"]')].filter(x=>x.getClientRects().length);if(!els.length){e.preventDefault();return}const first=els[0],last=els[els.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}
watch(()=>route.fullPath,()=>{if(current.value)close()})
onUnmounted(()=>{dialog.value?.close();cleanup()})
</script>
<template><dialog ref="dialog" class="nt-dialog" :class="{drawer:isDrawer,closing,video:current?.type==='video'}" aria-labelledby="overlay-title" @cancel="cancel" @keydown="keydown"><template v-if="current"><header class="overlay-header"><h2 id="overlay-title" tabindex="-1" data-initial-focus>{{ $tr(current.title) }}</h2><button class="overlay-close" :aria-label="$tr(&quot;关闭&quot;)" @click="close">×</button></header><div class="overlay-body">
<template v-if="isDrawer"><nav class="drawer-nav"><RouterLink :to="path('/')" @click="close">{{ $tr("首頁") }}</RouterLink><div v-for="g in navGroups" :key="g.label"><button :aria-expanded="expanded===g.label" @click="expanded=expanded===g.label?'':g.label">{{ $tr(g.label) }}<Icon name="chevron-down"/></button><div v-if="expanded===g.label" class="drawer-subnav"><RouterLink v-if="g.path" :to="path(g.path)" @click="close">{{ $tr("AI 量化總覽") }}</RouterLink><RouterLink v-for="item in g.items" :key="item[0]" :to="path(item[2])" @click="close">{{ $tr(item[0]) }}<small>{{ $tr(item[1]) }}</small></RouterLink></div></div><RouterLink :to="path('/news')" @click="close">{{ $tr("新聞") }}</RouterLink><RouterLink :to="path('/charity')" @click="close">{{ $tr("公益") }}</RouterLink></nav><div class="drawer-account"><div v-if="session.loggedIn" class="mode-toggle"><button v-for="m in ['真實','模擬']" :key="m" :class="{active:session.mode===m}" @click="session.mode=m">{{ $tr(m) }}</button></div><button class="primary-button wide-button" @click="navigate(session.loggedIn?'/assets':'/login')">{{ $tr(session.loggedIn?'資產':'登入') }}</button><button class="secondary-button wide-button" @click="navigate('/profile')">{{ $tr("個人資料") }}</button><button v-if="session.loggedIn" @click="logout();close()">{{ $tr("登出") }}</button></div><p class="muted">{{ $tr("語言") }}</p><div class="language-list"><button v-for="[code,name] in languages" :key="code" @click="changeLanguage(code)">{{ $tr(name) }}<Icon v-if="locale===code" name="check" green/></button></div></template>
<template v-else-if="current.type==='video'"><p class="muted">{{ $tr("用一段短片帶你了解策略如何構建、回測與運行。") }}</p><video controls playsinline preload="metadata" src="/newtrend/assets/ai-quant.mp4" :aria-label="$tr(&quot;AI Quant 運作機制影片&quot;)" @error="error='影片載入失敗，請稍後再試。'"></video></template>
<template v-else-if="current.type==='language'"><div class="language-list"><button v-for="[code,name] in languages" :key="code" @click="changeLanguage(code)">{{ $tr(name) }}<Icon v-if="locale===code" name="check" green/></button></div></template>
<template v-else-if="current.type==='support'"><p class="muted">{{ $tr("歡迎聯絡 NewQuantCapital 客服") }}</p><div class="card section-gap"><p>{{ $tr("您好，有什麼可以幫助您？") }}</p></div><form class="form-stack section-gap" @submit.prevent="done=true"><label>{{ $tr("訊息") }}<textarea v-model="message" rows="4" :placeholder="$tr(&quot;請描述您的問題&quot;)" required></textarea></label><button class="primary-button" :disabled="!message.trim()||done">{{ $tr("發送") }}</button><p class="notice">{{ $tr("本地展示不會發送訊息至原站客服。") }}</p><p v-if="done" role="status" class="positive">{{ $tr("演示訊息已顯示，未發送至外部。") }}</p></form></template>
<template v-else-if="current.type==='wallet'"><p class="notice">{{ $tr("本地前端演示不會要求錢包授權或簽名。") }}</p><button class="primary-button wide-button section-gap" @click="login();done=true" :disabled="done">{{ $tr("連接演示錢包") }}</button><p v-if="done" role="status" class="positive section-gap">{{ $tr("已連接本地演示帳戶") }}</p></template>
<template v-else-if="current.type==='messages'"><div class="empty"><Icon name="mail"/><p>{{ $tr("暫無新訊息") }}</p></div></template>
<template v-else-if="current.type==='account-edit'"><form id="account-action" class="form-stack" @submit.prevent="accountAction"><label>{{ $tr(current.title) }}<input v-model="message" maxlength="60" :aria-label="$tr(current.title)"/></label></form></template>
<template v-else-if="current.type==='account-confirm'"><p class="muted">{{ $tr(current.data.description) }}</p><form id="account-action" @submit.prevent="accountAction"></form></template>
<template v-else-if="current.type==='vip'"><div class="card"><small>{{ $tr("當前等級") }}</small><p class="metric">{{ $tr("VIP 0") }}</p><p class="muted">{{ $tr("距 VIP 1 還需 100,000 USD") }}</p></div><h3 class="section-gap">{{ $tr("等級階梯") }}</h3><div v-for="(amount,index) in [0,100000,500000,1000000,5000000,10000000]" :key="index" class="summary-line" style="padding:16px 0;border-bottom:1px solid #ffffff0b"><strong>{{ $tr("VIP ") }}{{ $tr(index) }}</strong><span>{{ $tr(fmt(amount)) }}{{ $tr(" USD") }}</span></div></template>
<template v-else-if="formType"><div v-if="current.data.name" class="summary-line product-summary"><div class="coin-label"><Coin :symbol="current.data.symbol||'USD'"/><div><strong>{{ $tr(current.data.name) }}</strong><small class="muted" style="display:block;margin-top:6px">{{ $tr(current.data.symbol||'USD') }} · {{ $tr(current.data.days?current.data.days+' 天':'活期') }}</small></div></div><span v-if="current.data.rate" class="metric">{{ $tr(current.data.rate) }}%</span></div><form id="action-form" class="form-stack" @submit.prevent="submit"><div class="summary-line"><label for="action-amount">{{ $tr(current.type==='order'?'委託數量':'申購金額') }}</label><small class="muted">{{ $tr("可用餘額 ") }}{{ $tr(session.mode==='模擬'?'100,000':'0') }} {{ $tr(current.data.symbol||'USD') }}</small></div><input id="action-amount" v-model="amount" inputmode="decimal" :placeholder="$tr(&quot;請輸入金額&quot;)" :aria-invalid="Boolean(error)" aria-describedby="action-error" :disabled="done"/><small class="muted">{{ $tr("起投 ") }}{{ $tr(fmt(current.data.min??.01)) }} {{ $tr(current.data.symbol||'USD') }}{{ $tr(" · 本地模擬操作") }}</small><div class="card"><small class="muted">{{ $tr(current.type==='order'?'委託摘要':'預計收益') }}</small><p style="margin-top:12px">{{ $tr(current.type==='order'?(current.data.description||current.data.name):amount?fmt(estimate)+' '+(current.data.symbol||'USD'):'輸入金額後顯示預計收益') }}</p><div v-if="current.data.days" class="timeline"><div><small>{{ $tr("申購") }}</small>{{ $tr("現在") }}</div><div><small>{{ $tr("起息") }}</small>{{ $tr("審核通過後次日") }}</div><div><small>{{ $tr("到期") }}</small>{{ $tr(current.data.days) }}{{ $tr(" 天後") }}</div></div></div><p v-if="done" class="form-success" role="status">{{ $tr("演示操作已完成，沒有發送真實交易。") }}</p></form></template>
<template v-else><p class="muted">{{ $tr(current.data.description||'這是本地介面演示，未連接原站帳戶服務。') }}</p></template>
<p v-if="error" id="action-error" class="form-error section-gap" role="alert">{{ $tr(error) }}</p>
</div><footer v-if="!isDrawer&&current.type!=='video'" class="overlay-footer"><button class="secondary-button" @click="close">{{ $tr(done?'關閉':'取消') }}</button><button v-if="['account-edit','account-confirm'].includes(current.type)" class="primary-button" form="account-action" type="submit" :disabled="done">{{ $tr("確認") }}</button><button v-if="formType" class="primary-button" form="action-form" :disabled="done||!amount" type="submit">{{ $tr(done?'已完成':current.type==='order'?'確認委託':'確認') }}</button></footer></template></dialog></template>
<style scoped>
.nt-dialog{margin:auto;padding:0;width:min(512px,calc(100vw - 32px));max-height:calc(100vh - 32px);max-height:calc(100dvh - 32px);border:1px solid #ffffff12;border-radius:18px;background:#090d12;color:#fff;overflow:hidden;box-shadow:0 24px 100px #0008}.nt-dialog[open]{display:flex;flex-direction:column;animation:modal-in 200ms ease-out}.nt-dialog::backdrop{background:#0009;backdrop-filter:blur(7px);animation:fade-in 200ms ease-out}.nt-dialog.closing{animation:modal-out 150ms ease-in forwards}.nt-dialog.closing::backdrop{animation:fade-out 150ms ease-in forwards}.nt-dialog.video{width:min(768px,calc(100vw - 32px))}.overlay-header{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:16px 16px 8px 24px;flex-shrink:0}.overlay-header h2{font-size:1.125rem;line-height:1.5;overflow-wrap:anywhere}.overlay-close{width:44px;height:44px;border-radius:50%;font-size:1.625rem;flex-shrink:0;color:#fff9}.overlay-body{overflow-y:auto;overscroll-behavior:contain;padding:8px 24px 24px;min-height:0;scroll-padding:24px;padding-bottom:max(24px,env(safe-area-inset-bottom))}.overlay-body video{display:block;width:100%;aspect-ratio:16/9;margin-top:16px;border-radius:16px;background:#202226}.overlay-footer{display:flex;justify-content:flex-end;gap:16px;padding:16px 24px;flex-shrink:0;border-top:1px solid #ffffff08;padding-bottom:max(16px,env(safe-area-inset-bottom))}.product-summary{padding:8px 0 24px;border-bottom:1px solid #ffffff0c;margin-bottom:24px}.product-summary .metric{font-size:1.25rem}.language-list{display:grid;gap:4px}.language-list button{display:flex;align-items:center;justify-content:space-between;padding:16px 12px;text-align:left;border-radius:12px}.language-list button:hover{background:#ffffff08}.drawer{margin:0 auto 0 0;height:100vh;height:100dvh;max-height:100vh;max-height:100dvh;width:min(288px,calc(100vw - 48px));border-radius:0;background:#121415;padding-left:env(safe-area-inset-left)}.drawer[open]{animation:drawer-in 200ms ease-out}.drawer.closing{animation:drawer-out 150ms ease-in forwards}.drawer .overlay-header{padding:8px 8px 8px 20px;border-bottom:1px solid #ffffff05}.drawer .overlay-body{padding:8px 16px 24px}.drawer-nav>a,.drawer-nav>div>button{display:flex;justify-content:space-between;align-items:center;width:100%;text-align:left;padding:14px 4px}.drawer-subnav a{display:block;padding:12px 16px;font-size:0.875rem}.drawer-subnav small{display:block;color:#fff6;font-size:0.6875rem;margin-top:4px}.drawer-account{display:grid;gap:14px;margin:32px 0 24px}.drawer-account .mode-toggle{justify-content:center}.drawer-account .mode-toggle button{flex:1}.drawer-account .primary-button{padding:9px 20px}@keyframes modal-in{from{opacity:0;transform:scale(.96)}to{opacity:1;transform:scale(1)}}@keyframes modal-out{to{opacity:0;transform:scale(.96)}}@keyframes fade-in{from{opacity:0}to{opacity:1}}@keyframes fade-out{to{opacity:0}}@keyframes drawer-in{from{transform:translateX(-100%)}to{transform:translateX(0)}}@keyframes drawer-out{to{transform:translateX(-100%)}}@media(prefers-reduced-motion:reduce){.nt-dialog[open],.drawer[open]{animation:fade-in 40ms linear}.nt-dialog.closing,.drawer.closing{animation:fade-out 40ms linear}}
</style>
